export default async function Home() {
  const [plans, templates] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  ]);

  const OS_FAMILY_LABEL: Record<string, string> = {
    ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
    fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", opensuse: "openSUSE",
  };
  const byCat = (cat: string) => {
    const list = templates.filter((t) => t.category === cat);
    if (cat === "PLAIN_OS") {
      const seen = new Set<string>();
      const fams: string[] = [];
      for (const t of list) {
        const fam = (t.family || t.name).toLowerCase();
        if (seen.has(fam)) continue;
        seen.add(fam);
        fams.push(OS_FAMILY_LABEL[fam] ?? (t.family ? t.family[0].toUpperCase() + t.family.slice(1) : t.name));
      }
      return fams.length ? fams : FALLBACK[cat];
    }
    const live = list.map((t) => t.name);
    return live.length ? live : FALLBACK[cat];
  };

