import { db } from "@/lib/db";

async function main() {
  const card = await db.card.findFirst({
    where: { title: { contains: "Website Overhaul v2", mode: "insensitive" } },
    include: { board: { include: { columns: { orderBy: { position: "asc" } } } }, column: true },
  });
  if (!card) {
    console.log("CARD NOT FOUND");
    const cards = await db.card.findMany({ where: { title: { contains: "Overhaul", mode: "insensitive" } }, include: { board: true, column: true } });
    console.log("Overhaul-ish cards:", cards.map((c) => `${c.title} [${c.board.name} / ${c.column.name}]`));
    return;
  }
  console.log(`Found: "${card.title}" on board "${card.board.name}", column "${card.column.name}"`);
  console.log("Columns:", card.board.columns.map((c) => c.name).join(" | "));

  const done = card.board.columns.find((c) => /^done$/i.test(c.name)) || card.board.columns.find((c) => /done|complete|shipped/i.test(c.name));
  if (!done) {
    console.log("NO DONE COLUMN FOUND");
    return;
  }
  const maxPos = await db.card.aggregate({ where: { columnId: done.id }, _max: { position: true } });
  const newPos = (maxPos._max.position ?? -1) + 1;

  await db.card.update({ where: { id: card.id }, data: { columnId: done.id, position: newPos } });

  await db.cardComment.create({
    data: {
      cardId: card.id,
      authorName: "claude",
      body:
        "Shipped to production. The approved /v9 hero is now merged into the live marketing homepage (nxeon.cloud) via components/marketing/AnimatedHero.tsx.\n\n" +
        "What changed:\n" +
        "- New headline \"Everything you build, online in 60 seconds\" + the all-in-one product/audience subcopy, replacing \"Deploy a cloud VPS in seconds, not hours\".\n" +
        "- Swapped the developer shell terminal for the friendly non-terminal DeployStage visual (plain-language deploy steps resolving to a live-server card). Retained the animated hero background and all homepage sections below the hero.\n" +
        "- Honesty guards for the now-indexable page: omitted the /v9 ReviewBadges (placeholder Trustpilot/HostAdvice/Google scores — its own source forbids use on `/`) and swapped the unbacked \"30-day money-back\" chip for the established \"99.9% uptime SLA\".\n\n" +
        "/v9 route: REMOVED (its purpose is fulfilled now that the hero is live). Homepage stays indexable (robots index:true).\n\n" +
        "Deploy: commit 031978d pushed to main. Staging HTTP 200 on :8080, production promoted HTTP 200, nxeon-web active. Live verification: https://nxeon.cloud/ returns 200 and renders the new hero copy.",
    },
  });

  console.log(`MOVED to "${done.name}" (position ${newPos}) and added comment.`);
}

main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
